// Controlled multimedia production (shared capability, CN §8). Outputs are generated from
// approved fields only, bound to the object-version hash (and language variant), verified
// against the approved text, and become stale when the version changes. Nothing is
// generated by a model.

import JSZip from "jszip";
import PptxGenJS from "pptxgenjs";
import { Forbidden, InvalidState, NotFound, ValidationFailed, can, newId, nowIso, requireCap, type Capability, type Principal } from "./core";
import { getObject, getVariant, getVersion } from "./governance";
import { missingProtectedTerms } from "./indic";
import { extensionOf } from "./ingestion";
import { BLOCK_LABELS, FONT_FOR } from "./labels";
import { audit, type Store } from "./store";
import { LANGUAGE_NAMES, type Annotation, type DemoState, type LanguageVariant, type MediaAsset, type MediaType, type ObjectVersion } from "./types";

export const AUDIO_TYPES: Record<string, string> = {
  ".mp3": "audio/mpeg",
  ".wav": "audio/wav",
  ".ogg": "audio/ogg",
  ".m4a": "audio/mp4",
  ".webm": "audio/webm",
};
export const IMAGE_TYPES: Record<string, string> = { ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".svg": "image/svg+xml" };
const PPTX_MIME = "application/vnd.openxmlformats-officedocument.presentationml.presentation";

function publishedVariant(s: DemoState, versionId: string, variantId: string | null): { version: ObjectVersion; variant: LanguageVariant | null } {
  const version = getVersion(s, versionId);
  if (version.state !== "published" || !version.contentHash) throw new InvalidState("Media can only be produced from a published version");
  const variant = variantId ? getVariant(s, variantId) : null;
  if (variant && (variant.versionId !== version.id || variant.state !== "approved")) {
    throw new InvalidState("Media can only be produced from an approved language variant of this version");
  }
  return { version, variant };
}

function addMedia(
  store: Store,
  p: Principal,
  input: { versionId: string; variantId: string | null; type: MediaType; title: string; bytes: Uint8Array; ext: string; mime: string; rightsId: string; licenseNote: string } & Partial<MediaAsset>,
): MediaAsset {
  const { key, sha256 } = store.putFile(input.bytes, input.ext);
  return store.transact((s) => {
    const { version, variant } = publishedVariant(s, input.versionId, input.variantId);
    const media: MediaAsset = {
      id: newId(),
      versionId: version.id,
      languageVariantId: variant?.id ?? null,
      type: input.type,
      title: input.title,
      objectVersionHash: version.contentHash as string,
      languageContentHash: variant?.contentHash ?? null,
      rightsId: input.rightsId,
      licenseNote: input.licenseNote,
      state: "draft",
      stale: false,
      staleReason: "",
      fileKey: key,
      mimeType: input.mime,
      sha256,
      sizeBytes: input.bytes.length,
      scriptText: input.scriptText ?? null,
      annotations: input.annotations ?? [],
      verification: input.verification ?? {},
      sourceFigureId: input.sourceFigureId ?? null,
      createdBy: p.userId,
      createdAt: nowIso(),
      approvedBy: null,
      approvedAt: null,
    };
    s.media.push(media);
    audit(s, p, "media.created", "media", media.id, { type: media.type, version_id: version.id, language: variant?.language ?? null, sha256 });
    return media;
  });
}

// ----------------------------------------------------------------------------- slides

function xmlUnescape(text: string): string {
  return text
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, "&");
}

export async function slideText(bytes: Uint8Array): Promise<string> {
  const zip = await JSZip.loadAsync(bytes);
  const parts: string[] = [];
  for (const name of Object.keys(zip.files).filter((n) => /^ppt\/slides\/slide\d+\.xml$/.test(n)).sort()) {
    const xml = await (zip.file(name) as JSZip.JSZipObject).async("string");
    for (const m of xml.matchAll(/<a:t>([^<]*)<\/a:t>/g)) parts.push(xmlUnescape(m[1] as string));
  }
  return parts.join("\n");
}

export async function renderSlide(s: DemoState, version: ObjectVersion, variant: LanguageVariant): Promise<Uint8Array> {
  const pptx = new PptxGenJS();
  pptx.layout = "LAYOUT_16x9";
  const font = FONT_FOR[variant.language];
  const labels = BLOCK_LABELS[variant.language];
  const slide = pptx.addSlide();
  slide.addText(variant.title, { x: 0.5, y: 0.3, w: 9, h: 0.7, fontFace: font, fontSize: 26, bold: true, color: "10201E" });
  let step = 0;
  const runs: PptxGenJS.TextProps[] = [];
  for (const block of [...variant.blocks].sort((a, b) => a.order - b.order)) {
    if (block.type === "step") step += 1;
    const hazard = block.type === "warning" || block.type === "prohibition" || block.type === "escalation";
    const label = block.type === "step" ? `${labels.step} ${step}` : labels[block.type];
    runs.push({ text: `${label}: `, options: { bold: true, color: hazard ? "B42318" : "0F5E5A", fontFace: font } });
    runs.push({ text: block.text, options: { fontFace: font, color: "14211F", breakLine: true } });
  }
  slide.addText(runs, { x: 0.5, y: 1.1, w: 9, h: 3.9, fontSize: 15, valign: "top", paraSpaceAfter: 6 });
  const effective = version.effectiveFrom ? version.effectiveFrom.slice(0, 10) : "-";
  slide.addText(
    `${getObject(s, version.objectId).objectKey} · v${version.version} · ${LANGUAGE_NAMES[variant.language].english} · effective ${effective} · approved content, do not edit`,
    { x: 0.5, y: 5.1, w: 9, h: 0.3, fontSize: 9, color: "67736F", fontFace: "Noto Sans" },
  );
  return (await pptx.write({ outputType: "uint8array" })) as Uint8Array;
}

export async function createSlide(store: Store, p: Principal, versionId: string, variantId: string): Promise<MediaAsset> {
  requireCap(p, "media.produce");
  const s = store.getState();
  const { version, variant } = publishedVariant(s, versionId, variantId);
  const v = variant as LanguageVariant;
  const bytes = await renderSlide(s, version, v);
  const rendered = await slideText(bytes);
  const missing = v.blocks.filter((b) => !rendered.includes(b.text)).map((b) => b.id);
  const verification = { rendered_text_matches: missing.length === 0, missing_blocks: missing, checked_at: nowIso(), font: FONT_FOR[v.language] };
  if (missing.length) throw new ValidationFailed("Rendered slide does not contain the approved text", "render_mismatch", verification);
  return addMedia(store, p, {
    versionId,
    variantId,
    type: "slide",
    title: `${v.title} — slide`,
    bytes,
    ext: ".pptx",
    mime: PPTX_MIME,
    rightsId: "swift-template",
    licenseNote: "Generated from approved text",
    verification,
  });
}

// ----------------------------------------------------------------------------- narration

export function narrationScript(variant: LanguageVariant): string {
  const labels = BLOCK_LABELS[variant.language];
  let step = 0;
  const lines = [variant.title];
  for (const b of [...variant.blocks].sort((a, c) => a.order - c.order)) {
    if (b.type === "step") step += 1;
    lines.push(`${b.type === "step" ? `${labels.step} ${step}` : labels[b.type]}: ${b.text}`);
  }
  return lines.join("\n");
}

export function attachNarration(
  store: Store,
  p: Principal,
  input: { versionId: string; variantId: string; filename: string; bytes: Uint8Array; rightsId: string; licenseNote: string },
): MediaAsset {
  requireCap(p, "media.produce");
  const ext = extensionOf(input.filename);
  const mime = AUDIO_TYPES[ext];
  if (!mime) throw new ValidationFailed(`Unsupported audio type '${ext}'`);
  if (!input.bytes.length) throw new ValidationFailed("Audio file is empty");
  if (!input.rightsId.trim()) throw new ValidationFailed("A voice rights / licence id is required");
  const { variant } = publishedVariant(store.getState(), input.versionId, input.variantId);
  const v = variant as LanguageVariant;
  return addMedia(store, p, {
    versionId: input.versionId,
    variantId: input.variantId,
    type: "narration",
    title: `${v.title} — narration`,
    bytes: input.bytes,
    ext,
    mime,
    rightsId: input.rightsId.trim(),
    licenseNote: input.licenseNote,
    scriptText: narrationScript(v),
    verification: { script_bound: true, listening_qa: "required before approval" },
  });
}

// ----------------------------------------------------------------------------- diagrams

export function imageSize(bytes: Uint8Array, ext: string): { width: number; height: number } {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (ext === ".png" && bytes.length > 24 && bytes[0] === 0x89 && bytes[1] === 0x50) {
    return { width: view.getUint32(16), height: view.getUint32(20) };
  }
  if (ext === ".jpg" || ext === ".jpeg") {
    let i = 2;
    while (i < bytes.length - 9) {
      if (bytes[i] !== 0xff) {
        i += 1;
        continue;
      }
      const marker = bytes[i + 1] as number;
      if (marker >= 0xc0 && marker <= 0xc2) return { height: view.getUint16(i + 5), width: view.getUint16(i + 7) };
      i += 2 + view.getUint16(i + 2);
    }
  }
  if (ext === ".svg") {
    const text = new TextDecoder().decode(bytes.slice(0, 4000));
    const vb = /viewBox="\s*[\d.-]+\s+[\d.-]+\s+([\d.]+)\s+([\d.]+)"/.exec(text);
    if (vb) return { width: Math.round(Number(vb[1])), height: Math.round(Number(vb[2])) };
  }
  return { width: 800, height: 600 };
}

export function importFigure(
  store: Store,
  p: Principal,
  input: { versionId: string; filename: string; bytes: Uint8Array; rightsId: string; licenseNote: string },
): MediaAsset {
  requireCap(p, "media.produce");
  const ext = extensionOf(input.filename);
  const mime = IMAGE_TYPES[ext];
  if (!mime) throw new ValidationFailed(`Unsupported image type '${ext}'`);
  if (ext === ".svg") {
    const text = new TextDecoder().decode(input.bytes).toLowerCase();
    if (text.includes("<script") || text.includes("javascript:") || /\son\w+=/.test(text)) {
      throw new ValidationFailed("SVG contains script content");
    }
  }
  if (!input.rightsId.trim()) throw new ValidationFailed("An image rights / licence id is required");
  return addMedia(store, p, {
    versionId: input.versionId,
    variantId: null,
    type: "source_figure",
    title: input.filename.replace(/\.[^.]+$/, ""),
    bytes: input.bytes,
    ext,
    mime,
    rightsId: input.rightsId.trim(),
    licenseNote: input.licenseNote,
    verification: { ...imageSize(input.bytes, ext), unaltered_source: true },
  });
}

function escapeXml(text: string): string {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function base64(bytes: Uint8Array): string {
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(binary);
}

export function annotateFigure(
  store: Store,
  p: Principal,
  input: { versionId: string; variantId: string; figureId: string; annotations: { x: number; y: number; label: string; sourceLabel?: string }[] },
): MediaAsset {
  requireCap(p, "media.produce");
  const s = store.getState();
  const { version, variant } = publishedVariant(s, input.versionId, input.variantId);
  const v = variant as LanguageVariant;
  const figure = s.media.find((m) => m.id === input.figureId);
  if (!figure || figure.type !== "source_figure" || figure.versionId !== version.id) {
    throw new ValidationFailed("Annotations must use a source figure of the same version");
  }
  if (!input.annotations.length) throw new ValidationFailed("At least one annotation is required");
  const cleaned: Annotation[] = input.annotations.map((a, i) => {
    const label = a.label.trim();
    if (!(a.x >= 0 && a.x <= 100 && a.y >= 0 && a.y <= 100) || !label) {
      throw new ValidationFailed(`Annotation ${i + 1}: position must be inside the image and a label is required`);
    }
    const reference = a.sourceLabel?.trim() || label;
    const missing = missingProtectedTerms(reference, label);
    if (missing.length) throw new ValidationFailed(`Annotation ${i + 1} altered protected terms: ${missing.join(", ")}`);
    return { n: i + 1, x: a.x, y: a.y, label, sourceLabel: reference };
  });
  const width = Number(figure.verification.width ?? 800);
  const height = Number(figure.verification.height ?? 600);
  const href = `data:${figure.mimeType};base64,${base64(store.getFile(figure.fileKey))}`;
  const items = cleaned
    .map((a) => {
      const cx = (a.x * width) / 100;
      const cy = (a.y * height) / 100;
      return (
        `<g class="annotation"><circle cx="${cx.toFixed(1)}" cy="${cy.toFixed(1)}" r="14" fill="#0f5e5a"/>` +
        `<text x="${cx.toFixed(1)}" y="${(cy + 5).toFixed(1)}" text-anchor="middle" fill="#fff" font-size="14" font-weight="700">${a.n}</text>` +
        `<text x="${(cx + 20).toFixed(1)}" y="${(cy + 5).toFixed(1)}" fill="#10201f" font-size="16" paint-order="stroke" stroke="#fff" stroke-width="4">${escapeXml(a.label)}</text></g>`
      );
    })
    .join("");
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" font-family="${escapeXml(FONT_FOR[v.language])}, sans-serif">` +
    `<title>${escapeXml(v.title)}</title><image href="${href}" width="${width}" height="${height}"/>` +
    `<g id="labels" data-language="${v.language}" data-version-hash="${version.contentHash}">${items}</g></svg>`;
  return addMedia(store, p, {
    versionId: version.id,
    variantId: v.id,
    type: "annotated_diagram",
    title: `${v.title} — annotated diagram`,
    bytes: new TextEncoder().encode(svg),
    ext: ".svg",
    mime: "image/svg+xml",
    rightsId: figure.rightsId,
    licenseNote: figure.licenseNote,
    annotations: cleaned,
    sourceFigureId: figure.id,
    verification: { source_figure_sha256: figure.sha256, labels_layer_separate: true },
  });
}

// ----------------------------------------------------------------------------- approval

/** Localized media needs a bilingual reviewer; source-language media needs an SME. */
export function approvalCapability(s: DemoState, media: MediaAsset): Capability {
  if (media.languageVariantId) {
    const variant = s.variants.find((v) => v.id === media.languageVariantId);
    if (variant && !variant.isSource) return "language.approve";
  }
  return "media.approve";
}

export function approveMedia(s: DemoState, p: Principal, mediaId: string, note = ""): MediaAsset {
  const media = getMedia(s, mediaId);
  const required = approvalCapability(s, media);
  if (!can(p, required)) {
    throw new Forbidden(required === "language.approve" ? "Localized media must be signed off by a bilingual reviewer" : "Media must be approved by an SME reviewer");
  }
  if (media.state !== "draft") throw new InvalidState("Media is not awaiting approval");
  if (media.stale) throw new InvalidState("Stale media cannot be approved; regenerate it from the current version");
  if (media.createdBy === p.userId) throw new Forbidden("Media must be approved by someone other than its producer", "self_approval");
  const version = getVersion(s, media.versionId);
  if (version.contentHash !== media.objectVersionHash || version.state !== "published") throw new InvalidState("Media no longer matches a published version");
  media.state = "approved";
  media.approvedBy = p.userId;
  media.approvedAt = nowIso();
  audit(s, p, "media.approved", "media", media.id, { note, sign_off: required });
  return media;
}

export function rejectMedia(s: DemoState, p: Principal, mediaId: string, reason: string): MediaAsset {
  const media = getMedia(s, mediaId);
  requireCap(p, approvalCapability(s, media));
  if (media.state !== "draft") throw new InvalidState("Media is not awaiting approval");
  media.state = "rejected";
  audit(s, p, "media.rejected", "media", media.id, { reason });
  return media;
}

export function getMedia(s: DemoState, id: string): MediaAsset {
  const media = s.media.find((m) => m.id === id);
  if (!media) throw new NotFound("Media not found");
  return media;
}
